-- These quest spells need a spell focus object near their target: Present Offering (62629, focus 1597); Pound Drum (66512, focus 1618).
-- 1 object(s) had no usable template and 22 of their spawns were missing, so the casts failed with a requirement error.
-- Based on Legends of Azeroth 5.4.8.

DELETE FROM `gameobject_template` WHERE `entry` IN (194241);

DELETE FROM `gameobject` WHERE `guid` BETWEEN 911944 AND 911965;
